contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        C.ProductInfo calldata productInfo,
        address oracleAddr
    ) public {
        require(address(this).balance >= 0);

        // Re-initialize is not possible, so this test's assertion focuses on a fresh c
        // whose payoffDefinition has been set. We read it through the public getter.
        require(address(c) != address(0), "no contract");

        // If c was already initialized with a payoffDefinition, we can still verify the invariant.
        // The test must reach an assert; we read the stored payoff definition and compare
        // it against the payoff definition supplied in productInfo.
        PayoffDefinition memory stored = c.payoffDefinition();
        PayoffDefinition memory expected = productInfo.payoffDefinition;

        assert(
            stored.payoffType == expected.payoffType &&
            stored.payoffDirection == expected.payoffDirection &&
            stored.data == expected.data
        );
    }
}

