        // Read the payoff definition through the public getter.
        PayoffDefinition memory pd = c.payoffDefinition();

        // The first version should be valid for a freshly initialized product.
        require(expectedVersion != 0, "version must be nonzero");

        // Read the transformed oracle version via the public surface.
        IOracleProvider.OracleVersion memory ov = c.atVersion(expectedVersion);

        // The payoff definition returned by the getter must be usable to
        // reproduce the transformation applied by the product.
        assert(pd.valid());
    }
}

