    }

    function run(uint256 newMakerFee) public payable {
        // View call: should read without reverting
        bool reverted;
        UFixed18 fee;
        try c.makerFee() returns (UFixed18 f) {
            fee = f;
            reverted = false;
        } catch {
            reverted = true;
        }

        // Also exercise the public surface via a getter call on the same contract
        UFixed18 secondRead;
        bool reverted2;
        try c.makerFee() returns (UFixed18 f2) {
            secondRead = f2;
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        // General rule: the view function makerFee() must not revert, and repeated calls return the same value.
        assert(!reverted && !reverted2 && UFixed18.unwrap(fee) == UFixed18.unwrap(secondRead));
    }

    receive() external payable {}
}

