contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public {
        // precondition: positive amount
        require(amount > 0);

        // record before-values
        uint256 beforeCollateral = c.collateral();

        // make the deciding call through the public entry
        c.openTake(UFixed18.wrap(amount));

        // read after-values
        uint256 afterCollateral = c.collateral();

        // The fee is amount * price * takerFee() / 1e18
        IOracleProvider.OracleVersion memory oracleVersion = c.currentVersion();
        uint256 price = uint256(int256(Fixed18.unwrap(oracleVersion.price)));
        uint256 takerFee = uint256(UFixed18.unwrap(c.takerFee()));
        uint256 expectedFee = amount * price / 1e18 * takerFee / 1e18;

        assert(afterCollateral <= beforeCollateral && beforeCollateral - afterCollateral == expectedFee);
    }

    receive() external payable {}
}

